function conversationRow(c) { const last = c.messages.at(-1); return button('open-conversation', `${mark('chat', 'soft')}<span class="row-content"><strong>${esc(c.title)}</strong><small>${esc(last?.text || '새 이야기를 시작해 보세요')}</small></span><span class="row-date">${shortDate(c.at)}</span>`, 'conversation-row', `data-id="${c.id}"`); }
function conversations() {
  const filtered = data.conversations.filter(c => !ui.search || c.title.includes(ui.search) || c.messages.some(m => m.text.includes(ui.search))).sort((a, b) => b.at - a.at);
  return `${heading('대화', '생각이 이어지는 곳', button('new-chat', icon('compose'), 'header-button', 'aria-label="새 대화"'))}<label class="search-box">${icon('search')}<input id="conversation-search" type="search" placeholder="어떤 이야기를 나눴나요?" value="${esc(ui.search)}" aria-label="대화 검색"></label><div class="conversation-intro"><div class="mori-small"><img src="/assets/mori.svg" alt=""></div><div><h2>오늘은 어떤 이야기를 할까요?</h2><p>말로 해도, 글로 써도 이어지는 대화.</p></div></div><p class="list-label">${ui.search ? '검색 결과' : '최근 대화'} <span>${filtered.length}</span></p><div class="surface">${filtered.map(conversationRow).join('') || empty('chat', '아직 대화가 없어요', '모리에게 첫 부탁을 건네보세요.', button('new-chat', '대화 시작하기', 'primary-button'))}</div><div class="suggestion-card"><span class="tiny-label">이렇게 말해보세요</span><h3>“${data.customs[0]?.title || '퇴근 정리'} 실행해줘”</h3><p>내 기능을 찾아, 지난 부탁을 이어서.</p>${button('prompt', '모리에게 부탁하기 ' + icon('arrow'), 'text-button', `data-prompt="${esc(data.customs[0]?.title || '퇴근 정리')} 실행해줘"`)}</div>`;
}
function schedule() {
  const year = ui.month.getFullYear(), month = ui.month.getMonth(), first = new Date(year, month, 1), offset = first.getDay(), days = new Date(year, month + 1, 0).getDate();
  const selected = new Date(`${ui.date}T12:00:00`); const weekStart = new Date(selected); weekStart.setDate(selected.getDate() - selected.getDay());
  let dates = ui.calendar === 'month' ? Array.from({ length: Math.ceil((offset + days) / 7) * 7 }, (_, i) => new Date(year, month, i - offset + 1)) : Array.from({ length: 7 }, (_, i) => { const d = new Date(weekStart); d.setDate(d.getDate() + i); return d; });
  const events = data.events.filter(e => e.date === ui.date).sort((a, b) => a.time.localeCompare(b.time));
  const agenda = ui.calendar === 'week' ? dates.map(d => `<section class="week-agenda"><h3>${dateLabel(d)}</h3>${data.events.filter(e => e.date === dateKey(d)).sort((a,b) => a.time.localeCompare(b.time)).map(eventRow).join('') || '<p>비워둔 시간</p>'}</section>`).join('') : ui.calendar === 'day' ? `<div class="day-timeline">${Array.from({length: 17}, (_,i) => i+6).map(h => `<div class="timeline-hour"><span>${String(h).padStart(2,'0')}:00</span><div>${events.filter(e => Number(e.time.split(':')[0]) === h).map(eventRow).join('')}</div></div>`).join('')}</div>` : events.map(eventRow).join('');
  return `${heading('스케줄', '하루의 약속을 차근차근', button('new-event', icon('plus'), 'header-button', 'aria-label="일정 추가"'))}<div class="segmented">${[['month', '월'], ['week', '주'], ['day', '일']].map(([id, title]) => button('calendar-mode', title, ui.calendar === id ? 'selected' : '', `data-value="${id}" aria-pressed="${ui.calendar === id}"`)).join('')}</div>
    <div class="calendar-surface"><div class="month-header"><h2>${year}년 ${month + 1}월</h2><div>${button('month-prev', icon('back'), 'small-icon', 'aria-label="이전 기간"')}${button('calendar-today', '오늘', 'text-button')}${button('month-next', arrow, 'small-icon', 'aria-label="다음 기간"')}</div></div><div class="weekdays">${['일', '월', '화', '수', '목', '금', '토'].map(d => `<span>${d}</span>`).join('')}</div><div class="calendar-grid ${ui.calendar === 'day' ? 'compact' : ''}">${dates.map(d => { const key = dateKey(d), event = data.events.some(e => e.date === key); return button('select-date', `<span>${d.getDate()}</span>${event ? '<i></i>' : ''}`, `${key === ui.date ? 'selected' : ''} ${d.getMonth() !== month ? 'outside' : ''} ${key === dateKey(current()) ? 'today' : ''}`, `data-date="${key}" aria-label="${d.getMonth() + 1}월 ${d.getDate()}일${event ? ', 일정 있음' : ''}" aria-pressed="${key === ui.date}"`); }).join('')}</div></div>
    ${section(dateLabel(selected), `<span class="section-caption">일정 ${events.length}개</span>`)}<div class="surface">${agenda || empty('calendar', '비워둔 시간도 좋아요', '약속이나 나를 위한 시간을 더해보세요.', button('new-event', '일정 추가하기', 'secondary-button'))}</div><div class="quiet-card">${icon('spark')}<div><strong>말로 해도 같은 일정에 쏙.</strong><p>“내일 오후 2시 디자인 회의 잡아줘”</p></div>${button('prompt', icon('arrow'), 'small-icon', 'data-prompt="내일 오후 2시 디자인 회의 잡아줘" aria-label="말로 일정 추가 체험"')}</div>`;
}
function features() {
  return `${heading('기능', '모리가 할 수 있는 일', button('new-custom', icon('plus'), 'header-button', 'aria-label="새 기능 만들기"'))}<div class="segmented">${[['all', '모든 기능'], ['builtin', '기본 기능'], ['custom', '내 기능']].map(([v, title]) => button('feature-filter', title, ui.filter === v ? 'selected' : '', `data-value="${v}" aria-pressed="${ui.filter === v}"`)).join('')}</div>
    ${ui.filter !== 'custom' ? `${section('매일을 위한 기본 기능', tag('6가지'))}<div class="feature-grid">${BUILTINS.map(f => button('detail', `${mark(f.icon, f.color)}<h3>${f.title}</h3><p>${f.subtitle}</p><span class="feature-open">살펴보기 ${arrow}</span>`, 'feature-tile', `data-ref="${f.id}"`)).join('')}</div>` : ''}
    ${ui.filter !== 'builtin' ? `${section('나에게 맞춘 기능', `<span class="section-caption">${data.customs.length}개</span>`)}<div class="custom-list">${data.customs.map(f => button('detail', `${mark(f.icon, 'purple')}<span class="row-content"><strong>${esc(f.title)}</strong><small>${esc(f.time ? `${f.repeat} ${clockLabel(f.time)}` : '필요할 때 실행')}</small></span>${tag(!f.work ? '초안' : f.active ? '사용 중' : '중지', f.active ? 'green' : '')}${arrow}`, 'custom-row', `data-ref="custom:${f.id}"`)).join('')}</div><button class="create-feature" data-action="new-custom"><span class="create-icon">${icon('spark')}</span><h3>나만을 위한 부탁을<br>기능으로 만들어보세요.</h3><p>언제, 무엇을 하면 좋을지 말만 해주세요.</p><span>새 기능 만들기 ${icon('plus')}</span></button>` : ''}`;
}
function my() { return `${heading('마이', '나에게 더 잘 맞는 모리')}<div class="profile-card"><div class="profile-art"><img src="/assets/mori.svg" alt="모리"></div><h2>${esc(data.profile.name)}님</h2><p>작은 부탁으로 채워가는 나의 하루</p>${button('edit-profile', '프로필 편집', 'pill-button')}</div><div class="license-card"><div>${tag(data.profile.pro ? 'Pro 체험' : 'Free')}<h3>나에게 맞는 모리</h3><p>내가 만든 기능 ${data.customs.length}개 · 기록 ${data.notes.length + data.documents.length}개</p></div>${button('license', '둘러보기 ' + arrow, 'text-button')}</div>
    ${section('내 하루에 맞춰')}<div class="settings-list">${button('edit-profile', `${mark('sun', 'amber')}<span>출근 시간</span><small>${clockLabel(data.profile.commute)}</small>${arrow}`, 'setting-row')}${toggleRow('recent', '대시보드 최근 대화', 'chat', data.profile.recent)}${toggleRow('notify', '앱 안에서 알림 표시', 'bell', data.profile.notify)}${toggleRow('reduced', '움직임 줄이기', 'leaf', data.profile.reduced)}</div>
    ${section('앱 체험')}<div class="settings-list">${button('day-preview', `${mark('clock', 'blue')}<span>하루 미리보기</span><small>${time(current())}</small>${arrow}`, 'setting-row')}${button('guide', `${mark('compass', 'green')}<span>시나리오 둘러보기</span>${arrow}`, 'setting-row')}${button('account', `${mark('shield', 'purple')}<span>실제 계정 연결</span><small>${ui.liveUser ? '연결됨' : '선택 사항'}</small>${arrow}`, 'setting-row')}${button('reset', `${mark('repeat', 'soft')}<span>체험 데이터 초기화</span>${arrow}`, 'setting-row')}</div><p class="preview-explanation">이 화면은 기기에 저장되는 앱 체험이에요.<br>뉴스·시세는 예시이며, 결제와 기기 푸시는 실행되지 않아요.</p><div class="brand-footer">mori <span>작은 부탁, 가벼운 하루.</span></div>`; }
function toggleRow(key, title, name, checked) { return button('preference', `${mark(name, 'soft')}<span>${title}</span><span class="switch ${checked ? 'on' : ''}"><i></i></span>`, 'setting-row', `data-key="${key}" role="switch" aria-checked="${checked}"`); }
function render() {
  const main = $('#main');
  const previousScroll = main.scrollTop;
  const oldCarousel = $('#time-carousel');
  const oldIndex = oldCarousel?.firstElementChild ? Math.round(oldCarousel.scrollLeft / (oldCarousel.firstElementChild.getBoundingClientRect().width + 12)) : 0;
  const cardRef = oldCarousel?.children[oldIndex]?.dataset.ref;
  main.innerHTML = ({ dashboard, schedule, conversations, features, my }[ui.view] || dashboard)();
  main.classList.toggle('has-composer', ui.view === 'dashboard');
  main.scrollTop = previousScroll;
  $('#tabs').innerHTML = [['dashboard', 'home', '대시보드'], ['schedule', 'calendar', '스케줄'], ['conversations', 'chat', '대화'], ['features', 'grid', '기능'], ['my', 'user', '마이']].map(([v, i, label]) => `<button type="button" data-view="${v}" ${v === ui.view ? 'aria-current="page"' : ''}>${icon(i)}<span>${label}</span></button>`).join('');
  $('#quick-composer').hidden = ui.view !== 'dashboard'; document.documentElement.classList.toggle('reduce-motion', data.profile.reduced);
  const carousel = $('#time-carousel'); if (carousel) {
    const index = [...carousel.children].findIndex(card => card.dataset.ref === cardRef);
    if (index > 0) carousel.scrollLeft = index * (carousel.firstElementChild.getBoundingClientRect().width + 12);
    const syncDots = () => { const currentIndex = Math.round(carousel.scrollLeft / (carousel.firstElementChild.getBoundingClientRect().width + 12)); document.querySelectorAll('.carousel-dots button').forEach((el, i) => el.classList.toggle('active', i === currentIndex)); };
    carousel.addEventListener('scroll', syncDots, { passive: true }); syncDots();
  }
}
function route() { const next = location.hash.slice(1); ui.view = ['dashboard', 'schedule', 'conversations', 'features', 'my'].includes(next) ? next : 'dashboard'; render(); $('#main').scrollTop = 0; }
function go(view) { if (location.hash === `#${view}`) route(); else location.hash = view; }
function openSheet(title, content, cls = '') { ++ui.accountEpoch; ui.detail = null; $('#sheet-title').textContent = title; $('#sheet-content').innerHTML = content; $('#sheet').className = `sheet ${cls}`; if (!$('#sheet').open) $('#sheet').showModal(); $('#sheet-content').scrollTop = 0; }
function closeSheet() { $('#sheet').close(); ui.detail = null; }
const field = (label, name, value = '', type = 'text', extra = '') => `<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const textArea = (label, name, value = '', extra = '') => `<label class="field"><span>${label}</span><textarea name="${name}" rows="4" ${extra}>${esc(value)}</textarea></label>`;
function parkingForm(live = false) { const p = live ? ui.liveParking : data.parking; openSheet(live ? '계정에 주차 위치 저장' : '주차 위치 기억하기', `<form id="${live ? 'live-parking' : 'parking-form'}"><div class="form-intro">${mark('car')}<h3>어디에 주차하셨나요?</h3><p>${live ? '연결된 실제 Mori 계정에 저장해요.' : '이 기기에 기억하고, 출근길에 보여드려요.'}</p></div><div class="field-pair">${field('층', 'floor', p?.floor || '지하 3층', 'text', 'required maxlength="32"')}${field('구역 · 자리', 'spot', p?.spot || 'B16', 'text', 'maxlength="32"')}</div><div class="inline-info">${icon('sun')}출근 시간 ${clockLabel(data.profile.commute)} · ${data.profile.parkingLead ?? 30}분 전부터 카드에 표시</div><p class="form-error" role="alert"></p><button class="primary-button" type="submit">이 위치 기억하기 ${icon('check')}</button></form>`); }
function noteForm(id) { const n = data.notes.find(n => n.id === id); openSheet(n ? '메모 편집' : '생각 남기기', `<form id="note-form" data-id="${n?.id || ''}">${field('제목', 'title', n?.title || '', 'text', 'maxlength="80" placeholder="떠오른 생각에 이름을 붙여보세요"')}${textArea('내용', 'body', n?.body || '', 'placeholder="짧은 한 줄이어도 좋아요." maxlength="12000"')}<button class="primary-button" type="submit">메모 저장 ${icon('check')}</button></form>`); }
function eventForm(id) { const e = data.events.find(e => e.id === id); openSheet(e ? '일정 편집' : '새로운 약속', `<form id="event-form" data-id="${e?.id || ''}">${field('어떤 약속인가요?', 'title', e?.title || '', 'text', 'required maxlength="80" placeholder="예: 모리 디자인 미팅"')}<div class="field-pair">${field('날짜', 'date', e?.date || ui.date, 'date', 'required')}${field('시간', 'time', e?.time || '14:00', 'time', 'required')}</div>${field('장소', 'place', e?.place || '', 'text', 'maxlength="120" placeholder="선택 사항"')}<button class="primary-button" type="submit">일정 저장 ${icon('check')}</button>${e ? button('delete-event', '이 일정 삭제', 'danger-button', `data-id="${e.id}"`) : ''}</form>`); }
function customForm(id) { const f = data.customs.find(f => f.id === id); openSheet(f ? '내 기능 편집' : '나만의 기능 만들기', `<div class="form-intro">${mark('spark', 'purple')}<h3>어떤 부탁을 기억할까요?</h3><p>반복하는 작은 일을 모리에게 맡겨보세요.</p></div>${!f ? button('custom-example', '“평일 저녁 7시에 메모를 모아 할 일로 정리해줘”', 'example-request') : ''}<form id="custom-form" data-id="${f?.id || ''}">${field('기능 이름', 'title', f?.title || '', 'text', 'maxlength="60" placeholder="예: 퇴근 정리"')}${textArea('무엇을 하면 좋을까요?', 'work', f?.work || '', 'maxlength="2000" placeholder="오늘 저장한 메모를 모아서 할 일을 정리해줘"')}${field('짧은 설명', 'description', f?.description || '', 'text', 'maxlength="180" placeholder="선택 사항"')}${textArea('참고할 내용 · 선택', 'content', f?.content || '', 'maxlength="6000" placeholder="정리할 자료나 기억해야 할 내용을 남겨주세요"')}<div class="field-pair">${field('실행 시간 · 선택', 'time', f?.time || '', 'time')}<label class="field"><span>반복</span><select name="repeat">${['필요할 때', '매일', '평일', '한 번'].map(v => `<option ${f?.repeat === v ? 'selected' : ''}>${v}</option>`).join('')}</select></label></div><p class="field-help">시간 없이 저장하면 필요할 때 실행할 수 있어요.<br>체험 예약은 앱을 열고 있는 동안에만 진행돼요.</p><button class="primary-button" type="submit">${f ? '변경 저장' : '내 기능으로 저장'} ${icon('spark')}</button></form>`); }
function remaining(target) { const total = Math.max(0, Math.ceil((target - current()) / 1000)); return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`; }
const articleTitles = ['우리의 일상으로 들어온 작은 AI 비서', '새로운 도구보다 중요한 건, 좋은 질문', '덜 복잡하게 일하는 사람들의 공통점'];
