  if (busy.has(ui.chatId)) $('#messages').insertAdjacentHTML('beforeend', `<div class="assistant-progress" role="status"><span class="typing"><i></i><i></i><i></i></span> 내 기능과 요청을 확인하고 있어요</div>`);
