  if (a === 'new-chat') { $('#chat-input').value = ''; return openChat(); }
  if (a === 'open-conversation') { $('#chat-input').value = ''; return openChat(id); }
  if (a === 'close-chat') { $('#chat-panel').close(); return render(); }
  if (a === 'prompt') return prompt(el.dataset.prompt);
  if (a === 'chat-example') return send(el.dataset.prompt);
  if (a === 'voice') return openVoice();
