  if (a === 'month-prev' || a === 'month-next') { const delta = a === 'month-prev' ? -1 : 1; if (ui.calendar === 'month') { ui.month.setMonth(ui.month.getMonth() + delta); ui.date = dateKey(ui.month); } else { const d = new Date(ui.date + 'T12:00:00'); d.setDate(d.getDate() + delta * (ui.calendar === 'week' ? 7 : 1)); ui.date = dateKey(d); ui.month = new Date(d); ui.month.setDate(1); } return render(); }
